 function request(data,transfer=[]){return new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{if(waiter===pending){waiter=null;worker?.terminate();worker=null;reject(Error('Image reading took too long. Try one screenshot at a time.'));}},data.type==='load'?15000:180000),pending={resolve:value=>{clearTimeout(timeout);resolve(value)},reject:error=>{clearTimeout(timeout);reject(error)}},token=serial;waiter=pending;if(localProcess)localProcess({...data,cancelled:()=>token!==serial},message=>{if(waiter===pending)receive(message)});else worker.postMessage(data,transfer)});}
